local a={}a.FLOOR=0.02;a.RATIO=3.0;a.GIMBAL_DEG=3.0;a.HEADING_DEG=10.0;local function b(c)return c>=0 and 1 or-1 end;a._signOf=b;function a.gate(d,e,f,g)f=f or a.FLOOR;g=g or a.RATIO;d=math.abs(d)e=math.abs(e)if d<f then return"too-small"end;if e>0 and d<g*e then return"too-ambiguous"end;return"ok"end;function a.classifyScalarSign(h,i,j)j=j or{}local f=j.floor or a.FLOOR;local k=i-h;return{sign=b(k),magnitude=math.abs(k),status=math.abs(k)>=f and"ok"or"too-small"}end;function a.classifyGimbalAxis(l,m,j)j=j or{}local n=j.degThreshold or a.GIMBAL_DEG;local o=(m[1]or 0)-(l[1]or 0)local p=(m[2]or 0)-(l[2]or 0)local q,r,s;if math.abs(o)>=math.abs(p)then q,r,s=1,o,p else q,r,s=2,p,o end;local t=math.abs(r)>n and"deg"or"rad"local u=t=="deg"and math.pi/180 or 1;return{idx=q,sign=b(r),unit=t,scale=u,dominant=math.abs(r),runnerUp=math.abs(s),status=a.gate(r,s,j.floor,j.ratio)}end;function a.classifyLateralPair(l,v,w,j)j=j or{}local f,g=j.floor,j.ratio;local x=(v.front or 0)-(l.front or 0)local y=(v.rear or 0)-(l.rear or 0)local z=(w.front or 0)-(l.front or 0)local A=(w.rear or 0)-(l.rear or 0)local B,C=b(x),b(y)local D=a.gate(x+y,x-y,f,g)local E=B*z-C*A;local F=B*z+C*A;local G=j.yawFloor or a.FLOOR;local H=math.abs(E)>=G and"ok"or"too-small"return{signFront=B,signRear=C,signYawRate=b(E),swayStatus=D,yawStatus=H,swayOk=D=="ok",yawOk=H=="ok",yawDiff=E,yawComm=F}end;function a.detectHeadingScale(I,J,j)j=j or{}local n=j.degThreshold or a.HEADING_DEG;local f=j.floor or a.FLOOR;local k=J-I;local t=math.abs(k)>n and"deg"or"rad"local u=t=="deg"and math.pi/180 or 1;return{sign=b(k),scale=u,unit=t,magnitude=math.abs(k),status=math.abs(k)>=f and"ok"or"too-small"}end;function a.headingSignScale(I,J,K,j)j=j or{}local n=j.degThreshold or a.HEADING_DEG;local f=j.floor or a.FLOOR;local L=j.headingFloor or a.FLOOR;local k=J-I;local t=math.abs(k)>n and"deg"or"rad"local u=t=="deg"and math.pi/180 or 1;local M=math.abs(k)>=L;local N=math.abs(K)>=f;local O=b(K)*b(k)return{sign=O,scale=u,unit=t,mag